import React from 'react';
import { connect } from 'react-redux';
import { Input } from 'reactstrap';

import {
  fetchAllGuardiansService,
  saveGuardianService,
  fetchGuardianService,
  updateGuardianService,
  deleteGuardianService,
  fetchUnMappedGuardiansService,
  fetchSchoolGuardiansService,
} from 'actions/admin/guardians';
import GuardianFormModal from './components/GuardianFormModal.jsx';
import {
  formResMessage,
  formUsernameFromEmail,
  getGlobalCurrentBatchUtils,
  getGlobalSchoolUtils,
  usernameTextColor,
} from '../../../utils/commonFunc.js';
import { store } from '../../../index.js';
import { showToast } from '../../../actions/admin/auth.js';
import CustomButton from '../../../components/CustomButton.jsx';
import MuiTable from '../Common/MuiTable.jsx';
import StatTile from '../Common/StatTile.jsx';

class GuardianPage extends React.Component {
  constructor() {
    super();
    this.state = {
      schoolId: 0,
      isModalOpen: false,
      pageParams: {
        page: 1,
        size: 10,
      },
      // the search box, and the "not linked to a student" filter
      searchText: '',
      onlyUnlinked: false,
      // loaders
      guardiansFetching: false,
    };
  }

  isLoading = (name, value) => this.setState({ [name]: value });

  componentDidMount() {
    const globalSchool = getGlobalSchoolUtils();
    if (globalSchool) {
      this.setState({ schoolId: globalSchool.schoolId }, () => {
        this.fetchAllGuardians();
        this.fetchUnMappedGuardians(true);
      });
    } else {
      this.showWarning('Please select School', 'warning');
    }
  }

  fetchAllGuardians = async refetchAgain => {
    const { batchId } = getGlobalCurrentBatchUtils();
    if (batchId && (!this.props.guardiansData?.content?.length || refetchAgain)) {
      this.isLoading('guardiansFetching', true);
      await this.props.fetchAllGuardians({
        schoolId: this.state.schoolId,
        batchId,
        token: this.props.loggedUserToken,
        pageParams: this.state.pageParams,
      });
      this.isLoading('guardiansFetching', false);
    }
  };

  formModalOpen = () => this.setState({ isModalOpen: true });

  formModalClose = () => {
    this.setState({ isModalOpen: false });
  };

  saveGuardian = data => {
    data.school = { schoolId: this.state.schoolId };
    return this.props.saveGuardian({ postData: data, token: this.props.loggedUserToken });
  };

  fetchGuardian = guardianId => {
    return this.props.fetchGuardian({ guardianId, token: this.props.loggedUserToken }).then(() => this.formModalOpen());
  };

  updateGuardian = data => {
    return this.props.updateGuardian({
      guardianId: data.guardianId,
      postData: data,
      token: this.props.loggedUserToken,
    });
  };

  guardianUpdateSuccess = actionParam => {
    this.setState({ isModalOpen: false });
    this.showWarning(
      actionParam === 'add' ? 'Guardian added successfully' : 'Guardian Updated successfully',
      'success'
    );
    this.refreshLists();
  };

  // after an add, edit or delete: the page, the unlinked list and (when a search has read it) the school's guardian list
  refreshLists = () => {
    this.fetchUnMappedGuardians(true);
    this.fetchAllGuardians(true);
    if (this.props.schoolGuardians?.length) {
      this.props.fetchSchoolGuardians({ schoolId: this.state.schoolId, token: this.props.loggedUserToken });
    }
  };

  showWarning = (message, type) => {
    store.dispatch(showToast(message, type));
  };

  deleteGuardian = guardianId => {
    return this.props
      .deleteGuardian({ guardianId, token: this.props.loggedUserToken })
      .then(() => {
        this.refreshLists();
      })
      .catch(err => {
        this.showWarning(formResMessage(err), 'error');
      });
  };

  fetchPageData = page => {
    if (page !== this.state.pageParams.page) {
      this.setState(
        {
          pageParams: {
            ...this.state.pageParams,
            page,
          },
        },
        () => {
          this.fetchAllGuardians(true);
        }
      );
    }
  };

  fetchUnMappedGuardians = refetchAgain => {
    if (!this.props.unMappedGuardianList.length || refetchAgain) {
      this.props.fetchUnMappedGuardians({
        schoolId: this.state.schoolId,
        token: this.props.loggedUserToken,
      });
    }
  };

  // The page of guardians is read from the server without a search, so the first search reads the school's whole guardian list
  // once and filters that here.
  handleSearch = e => {
    const searchText = e.target.value;
    this.setState({ searchText });
    if (searchText.trim() && !this.props.schoolGuardians?.length) {
      this.props.fetchSchoolGuardians({ schoolId: this.state.schoolId, token: this.props.loggedUserToken });
    }
  };

  render() {
    const { isModalOpen, guardiansFetching, searchText, onlyUnlinked } = this.state;
    const { guardiansData, guardian, unMappedGuardianList, schoolGuardians } = this.props;
    const { startYear, endYear } = getGlobalCurrentBatchUtils() || {};

    const needle = searchText.trim().toLowerCase();
    const matches = el =>
      `${el.name || ''} ${el.email || ''} ${el.guardianMobile || ''}`.toLowerCase().includes(needle);
    const SEARCH_CAP = 50;
    // plain list: the server's page; searching: the school's guardians filtered here; the chip: the unlinked ones
    const source = onlyUnlinked ? unMappedGuardianList : needle ? schoolGuardians : guardiansData?.content;
    const found = (source || []).filter(el => !needle || matches(el));
    const rows = needle || onlyUnlinked ? found.slice(0, SEARCH_CAP) : found;
    const paged = !needle && !onlyUnlinked;
    const linked = guardiansData?.page?.totalElements ?? guardiansData?.totalElements ?? guardiansData?.content?.length;
    const unlinked = unMappedGuardianList?.length || 0;

    return (
      <div className="content">
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, marginBottom: 14, minHeight: 78 }}>
          <StatTile
            label={`Guardians in ${startYear && endYear ? `${startYear} - ${endYear}` : 'this batch'}`}
            value={linked ?? '–'}
            tone="info"
            minWidth={150}
            maxWidth={240}
          />
          <StatTile
            label="Not linked to a student"
            value={unlinked}
            tone={unlinked ? 'warn' : 'good'}
            note={unlinked ? (onlyUnlinked ? 'Showing them. Click to show all' : 'Click to show them') : undefined}
            active={onlyUnlinked}
            onClick={unlinked || onlyUnlinked ? () => this.setState({ onlyUnlinked: !onlyUnlinked }) : undefined}
            minWidth={150}
            maxWidth={240}
          />
        </div>
        <div className="rui-listbar" style={{ display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap' }}>
          <Input
            name="guardianSearch"
            style={{ width: 320, height: 36, borderRadius: 12, fontSize: 13 }}
            placeholder="Search by name, username or mobile..."
            value={searchText}
            onChange={this.handleSearch}
          />
          <div style={{ marginLeft: 'auto' }}>
            <CustomButton onClick={this.formModalOpen} name="Add Guardian" />
          </div>
        </div>
        <div className="rui-listarea">
          <MuiTable
            tableHeaders={['Relation', 'Name', 'Mobile', 'Education', 'Occupation', 'Income', 'Action']}
            tableBodyData={{
              ...(paged ? guardiansData : {}),
              content: rows.map(el => ({
                ...el,
                name: (
                  <span>
                    {el.name}{' '}
                    {el.email && <span style={{ color: usernameTextColor }}>({formUsernameFromEmail(el.email)})</span>}
                  </span>
                ),
              })),
            }}
            bodyColumns={['relation', 'name', 'guardianMobile', 'education', 'occupation', 'income', 'action']}
            dropDownActions={['edit', 'delete']}
            idName="guardianId"
            fetchItem={this.fetchGuardian}
            deleteItem={this.deleteGuardian}
            fetchPageData={this.fetchPageData}
            hidePagination={!paged}
            isLoading={guardiansFetching}
          />
          {!paged && found.length > SEARCH_CAP && (
            <div className="text-muted" style={{ fontSize: 12, marginTop: 6 }}>
              Showing the first {SEARCH_CAP} of {found.length}. Type more to narrow it down.
            </div>
          )}
        </div>
        <GuardianFormModal
          isModalOpen={isModalOpen}
          formModalCloseProp={this.formModalClose}
          saveGuardian={this.saveGuardian}
          guardian={guardian}
          updateGuardian={this.updateGuardian}
          guardianUpdateSuccess={this.guardianUpdateSuccess}
        />
      </div>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserId: state.auth.loggedUserId,
    loggedUserToken: state.auth.loggedUserToken,
    schools: state.schools.schoolList,
    guardiansData: state.guardians.guardiansData,
    guardian: state.guardians.guardian,
    unMappedGuardianList: state.guardians.unMappedGuardianList,
    schoolGuardians: state.guardians.guardianList,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    fetchAllGuardians: data => dispatch(fetchAllGuardiansService(data)),
    saveGuardian: data => dispatch(saveGuardianService(data)),
    fetchGuardian: data => dispatch(fetchGuardianService(data)),
    updateGuardian: data => dispatch(updateGuardianService(data)),
    deleteGuardian: data => dispatch(deleteGuardianService(data)),
    fetchUnMappedGuardians: data => dispatch(fetchUnMappedGuardiansService(data)),
    fetchSchoolGuardians: data => dispatch(fetchSchoolGuardiansService(data)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(GuardianPage);
